// Normalise + REDACT the failure record.
// Stack traces can echo request bodies that may contain Confidential/Restricted
// document text (Master Report s10 classification tiers, s19 DLP).
// Full detail goes to the on-disk log; only non-sensitive fields go to chat.

const MAX_MSG = 300;
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const exec = j.execution || {};
  const trig = j.trigger || {};
  const wf = j.workflow || {};
  const err = exec.error || trig.error || {};

  const rawMessage = String(err.message || 'unknown error');
  const safeMessage = rawMessage
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [REDACTED]')
    .replace(/("?(?:token|api[_-]?key|password|secret)"?\s*[:=]\s*)\S+/gi, '$1[REDACTED]')
    .slice(0, MAX_MSG);

  const isCritical = /AUDIT_CHAIN_BREAK|TAMPER/i.test(rawMessage);

  out.push({
    json: {
      event: 'workflow_failure',
      severity: isCritical ? 'critical' : 'error',
      critical: isCritical,
      occurred_at: new Date().toISOString(),
      workflow_id: wf.id || null,
      workflow_name: wf.name || null,
      execution_id: exec.id || null,
      execution_mode: exec.mode || trig.mode || null,
      retry_of: exec.retryOf || null,
      last_node: exec.lastNodeExecuted || null,
      error_message_safe: safeMessage,
      error_message_full: rawMessage,
      stack: String(err.stack || '').slice(0, 4000)
    }
  });
}

return out;

// Build a single newline-delimited JSON blob (full detail, local disk only).
const lines = $input.all()
  .map((i) => JSON.stringify(i.json))
  .join('\n') + '\n';

const day = new Date().toISOString().slice(0, 10);

return [{
  json: {
    log_path: `${$env.WB_LOG_DIR || '/data/n8n/logs'}/workflow-errors-${day}.jsonl`,
    summary: $input.all().map((i) => i.json)
  },
  binary: {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(lines, 'utf8'),
      `workflow-errors-${day}.jsonl`,
      'application/x-ndjson'
    )
  }
}];
